process is
    variable t_ini : cycle;      -- Tiempo inicial del pulso
    variable t_fin : cycle;      -- Tiempo final del pulso
    variable ancho_pulso : cycle;
begin
    wait until RB15 == '0';      -- Medimos el pulso de salida
    wait until RB15 == '1';
    t_ini := now();              -- El tiempo se mide en ciclos de reloj
    wait until RB15 == '0';
    t_fin := now();
    ancho_pulso := (t_fin - t_ini);  -- Ancho en ciclos. Reloj a X MHz
    -- El ancho del pulso ha de ser de YY ms
    -- que a XX MHz son YY ms * XX MHz = ZZ ciclos
    wait;
end process;

